import sys

data = sys.stdin.read().split()
n = int(data[0])
env = sorted((int(data[1 + 2 * i]), int(data[2 + 2 * i])) for i in range(n))
dp = [1] * n
for i in range(n):
    for j in range(i):
        if env[j][0] < env[i][0] and env[j][1] < env[i][1]:
            dp[i] = max(dp[i], dp[j] + 1)
print(max(dp))

